1	import { execFileSync, spawnSync } from "node:child_process";
2	import { createHash } from "node:crypto";
3	import {
4		existsSync,
5		mkdtempSync,
6		readFileSync,
7		rmSync,
8		writeFileSync,
9	} from "node:fs";
10	import { tmpdir } from "node:os";
11	import { join, relative, resolve, sep } from "node:path";
12	import { afterAll, describe, expect, it } from "vitest";
13	import { validateDeck } from "./lessonContent";
14	
15	/**
16	 * Evidence for the deck generation pipeline, read off its *output*.
17	 *
18	 * The generator is Python and this repository has no Python test framework;
19	 * adding one to gate content would put half this plan's evidence in a runner
20	 * nothing else uses. The generator's contract is what it emits, so that is
21	 * what is asserted over, from the runner already in use. `py_compile` gates
22	 * the scripts' syntax; everything below gates their behaviour.
23	 *
24	 * Three of these cases spawn the pipeline. They reach it through the scripted
25	 * vendor in `scripts/lesson_deck/testing/`, so no API call is made and no
26	 * credential is needed — the key below is a fake, and one case depends on it
27	 * being a fake it can search the output for.
28	 */
29	
30	const REPO_ROOT = resolve(import.meta.dirname, "..", "..", "..", "..");
31	const SCRIPTS = join(REPO_ROOT, "scripts");
32	const FIXTURES = join(SCRIPTS, "lesson_deck", "fixtures");
33	const FIXTURE_ROOT = join(FIXTURES, "generated");
34	const FIXTURE_LESSON = join(FIXTURE_ROOT, "lesson-02");
35	
36	/**
37	 * Not a credential. It is shaped like one so that the scan for key-shaped
38	 * strings would find it if the pipeline ever wrote it down, and the
39	 * scripted vendor echoes it back in its error text the way a real API echoes
40	 * a rejected request.
41	 */
42	const FAKE_KEY = "sk_fixturekey000000000000000000000";
43	
44	const readJson = (path: string): unknown =>
45		JSON.parse(readFileSync(path, "utf-8"));
46	
47	const fixtureDeck = readJson(join(FIXTURE_LESSON, "deck.json")) as Record<
48		string,
49		unknown
50	>;
51	const fixtureManifest = readJson(join(FIXTURE_LESSON, "manifest.json")) as {
52		schema: { segmentStates: string[]; verificationOutcomes: string[] };
53		assets: {
54			key: string;
55			kind: string;
56			state: string;
57			language: string | null;
58			inputHash: string;
59			contentHash: string | null;
60			path: string | null;
61			file: string | null;
62			verification: { outcome: string; attempts: number } | null;
63			failure: string | null;
64		}[];
65	};
66	
67	const temporaries: string[] = [];
68	function temporaryRoot(): string {
69		const created = mkdtempSync(join(tmpdir(), "lesson-deck-"));
70		temporaries.push(created);
71		return created;
72	}
73	afterAll(() => {
74		for (const path of temporaries)
75			rmSync(path, { recursive: true, force: true });
76	});
77	
78	interface RunResult {
79		status: number | null;
80		stdout: string;
81		stderr: string;
82	}
83	
84	function runScripted(
85		scenario: string,
86		assetsRoot: string,
87		scriptOverride?: string,
88	): RunResult {
89		const args = [
90			join(SCRIPTS, "lesson_deck", "testing", "run_scripted.py"),
91			"--scenario",
92			join(FIXTURES, scenario),
93			"--assets-root",
94			assetsRoot,
95		];
96		if (scriptOverride) args.push("--script", scriptOverride);
97		const result = spawnSync("python3", args, {
98			encoding: "utf-8",
99			env: { ...process.env, ELEVENLABS_API_KEY: FAKE_KEY },
100		});
101		return {
102			status: result.status,
103			stdout: result.stdout ?? "",
104			stderr: result.stderr ?? "",
105		};
106	}
107	
108	interface RunReport {
109		synthCalls: number;
110		transcribeCalls: number;
111		reused: number;
112		generated: number;
113		failed: number;
114		deckWritten: boolean;
115		errors: string[];
116	}
117	
118	function report(result: RunResult): RunReport {
119		expect(result.stderr).toBe("");
120		return JSON.parse(result.stdout) as RunReport;
121	}
122	
123	function checkPaths(
124		cases: { lessonId: unknown; assetPath: unknown }[],
125		assetsRoot: string,
126	): ({ ok: true; path: string; url: string } | { ok: false; error: string })[] {
127		const stdout = execFileSync(
128			"python3",
129			[
130				join(SCRIPTS, "lesson_deck", "testing", "check_paths.py"),
131				"--assets-root",
132				assetsRoot,
133			],
134			{ encoding: "utf-8", input: JSON.stringify(cases) },
135		);
136		return JSON.parse(stdout);
137	}
138	
139	describe("the deck a generation run emits", () => {
140		it("validates against the deck schema", () => {
141			const result = validateDeck(fixtureDeck);
142			if (!result.ok) {
143				throw new Error(
144					`fixture deck rejected: ${result.errors.map((e) => e.message).join("; ")}`,
145				);
146			}
147			expect(result.deck.lessonId).toBe("lesson-02");
148			expect(result.deck.slides.map((slide) => slide.kind)).toEqual([
149				"exposition",
150				"retrieval",
151				"reveal",
152				"rule",
153			]);
154		});
155	
156		it("carries one slide per slide the script declares, in script order", () => {
157			const declared = readFileSync(join(FIXTURES, "lesson-02.md"), "utf-8")
158				.split("\n")
159				.flatMap((line) => {
160					const match = /^##\s+[a-z]+\s+(\S+)\s*$/.exec(line);
161					return match ? [match[1]] : [];
162				});
163			expect(declared.length).toBeGreaterThan(0);
164			const slides = fixtureDeck.slides as { id: string }[];
165			expect(slides.map((slide) => slide.id)).toEqual(declared);
166		});
167	
168		it("references every clip and image the manifest generated", () => {
169			const referenced = new Set(
170				(fixtureDeck.slides as { audio?: string[]; image?: string }[]).flatMap(
171					(slide) => [
172						...(slide.audio ?? []),
173						...(slide.image ? [slide.image] : []),
174					],
175				),
176			);
177			const generated = fixtureManifest.assets.filter(
178				(asset) => asset.state === "generated",
179			);
180			expect(generated.length).toBeGreaterThan(0);
181			for (const asset of generated) {
182				expect([...referenced]).toContain(asset.path);
183			}
184			expect(referenced.size).toBe(generated.length);
185		});
186	});
187	
188	describe("asset paths", () => {
189		it("all resolve inside the lesson's own directory", () => {
190			const paths = [
191				...(fixtureDeck.slides as { audio?: string[]; image?: string }[]).flatMap(
192					(slide) => [
193						...(slide.audio ?? []),
194						...(slide.image ? [slide.image] : []),
195					],
196				),
197				...fixtureManifest.assets.flatMap((asset) =>
198					asset.path ? [asset.path] : [],
199				),
200			];
201			expect(paths.length).toBeGreaterThan(0);
202			for (const path of paths) {
203				expect(path.startsWith("/thai-script/lessons/lesson-02/")).toBe(true);
204				const onDisk = resolve(
205					FIXTURE_LESSON,
206					path.slice("/thai-script/lessons/lesson-02/".length),
207				);
208				expect(relative(FIXTURE_LESSON, onDisk).startsWith(`..${sep}`)).toBe(
209					false,
210				);
211				expect(existsSync(onDisk)).toBe(true);
212			}
213		});
214	
215		it("refuses a path that escapes the lesson directory, and a refused lesson id", () => {
216			const root = temporaryRoot();
217			const results = checkPaths(
218				[
219					{ lessonId: "lesson-02", assetPath: "audio/clip.mp3" },
220					{ lessonId: "lesson-02", assetPath: "../escape.mp3" },
221					{ lessonId: "lesson-02", assetPath: "audio/../../escape.mp3" },
222					{ lessonId: "lesson-02", assetPath: "/etc/passwd" },
223					{ lessonId: "Lesson-02", assetPath: "audio/clip.mp3" },
224					{ lessonId: "lessons/../../etc", assetPath: "audio/clip.mp3" },
225					{ lessonId: "l".repeat(65), assetPath: "audio/clip.mp3" },
226					{ lessonId: 2, assetPath: "audio/clip.mp3" },
227				],
228				root,
229			);
230	
231			expect(results[0]).toEqual({
232				ok: true,
233				path: join(root, "lesson-02", "audio", "clip.mp3"),
234				url: "/thai-script/lessons/lesson-02/audio/clip.mp3",
235			});
236			for (const refused of results.slice(1)) {
237				expect(refused.ok).toBe(false);
238			}
239			// The refusal names the key and never echoes the rejected value: a
240			// refused id is attacker-shaped and this text reaches logs.
241			for (const refused of results.slice(4)) {
242				if (refused.ok) throw new Error("expected a refusal");
243				expect(refused.error).not.toContain("etc");
244				expect(refused.error).not.toContain("Lesson-02");
245			}
246		});
247	
248		it("refuses a script whose image reaches outside the script's directory", () => {
249			// The read side of the same boundary. A lesson script is hand- and
250			// agent-authored and its image bytes are committed under
251			// `public/lessons/` and served, so an unconstrained `image:` publishes
252			// whatever the generator can read.
253			const home = temporaryRoot();
254			const secret = join(temporaryRoot(), "credentials");
255			writeFileSync(secret, "API_KEY=not-supposed-to-be-published");
256			const script = join(home, "escaping.md");
257			writeFileSync(
258				script,
259				readFileSync(join(FIXTURES, "lesson-02.md"), "utf-8").replace(
260					"image: images/district.svg",
261					`image: ${relative(home, secret)}`,
262				),
263			);
264	
265			const out = temporaryRoot();
266			const result = runScripted("clean.json", out, script);
267			expect(result.status).not.toBe(0);
268			expect(JSON.parse(result.stdout).refused).toContain(
269				"outside the directory holding the lesson script",
270			);
271			expect(existsSync(join(out, "lesson-02"))).toBe(false);
272		});
273	});
274	
275	describe("caching", () => {
276		it("records a hash for each asset that matches the committed bytes", () => {
277			expect(fixtureManifest.assets.length).toBeGreaterThan(0);
278			for (const asset of fixtureManifest.assets) {
279				expect(asset.state).toBe("generated");
280				if (!asset.file || !asset.contentHash) {
281					throw new Error(`${asset.key}: generated but records no file or hash`);
282				}
283				const bytes = readFileSync(join(FIXTURE_LESSON, asset.file));
284				expect(createHash("sha256").update(bytes).digest("hex")).toBe(
285					asset.contentHash,
286				);
287				// The cache key is in the filename, so a stale file cannot be
288				// served under the name of fresh inputs.
289				expect(asset.file).toContain(asset.inputHash.slice(0, 12));
290			}
291		});
292	
293		it("issues no API call when nothing in the script changed", () => {
294			const root = temporaryRoot();
295			const first = report(runScripted("clean.json", root));
296			expect(first.synthCalls).toBeGreaterThan(0);
297			expect(first.deckWritten).toBe(true);
298	
299			const second = report(runScripted("clean.json", root));
300			expect(second.synthCalls).toBe(0);
301			expect(second.transcribeCalls).toBe(0);
302			expect(second.reused).toBe(first.generated);
303		});
304	
305		it("regenerates only the edited segment and leaves the rest byte-identical", () => {
306			const root = temporaryRoot();
307			report(runScripted("clean.json", root));
308			const before = hashTree(join(root, "lesson-02"));
309	
310			// A copy of the script with one narration line reworded. The image it
311			// names is resolved relative to the script, so that moves with it.
312			const editDir = temporaryRoot();
313			execFileSync("cp", ["-r", join(FIXTURES, "images"), editDir]);
314			const edited = join(editDir, "edited.md");
315			const source = readFileSync(join(FIXTURES, "lesson-02.md"), "utf-8");
316			const reworded = source.replace(
317				"narration: en Answer out loud first, then turn the slide over.",
318				"narration: en Say your answer aloud, and only then turn the slide over.",
319			);
320			expect(reworded).not.toBe(source);
321			writeFileSync(edited, reworded);
322	
323			const second = report(runScripted("clean.json", root, edited));
324			expect(second.synthCalls).toBe(1);
325			expect(second.generated).toBe(1);
326	
327			const after = hashTree(join(root, "lesson-02"));
328			const unchanged = [...before].filter(([file]) => after.has(file));
329			// deck.json and manifest.json change; every other kept file is untouched.
330			expect(unchanged.length).toBe(before.size - 1);
331			for (const [file, hash] of unchanged) {
332				if (file.endsWith(".json")) continue;
333				expect(after.get(file)).toBe(hash);
334			}
335		});
336	});
337	
338	function hashTree(root: string): Map<string, string> {
339		const listing = execFileSync("find", [root, "-type", "f"], {
340			encoding: "utf-8",
341		})
342			.split("\n")
343			.filter(Boolean);
344		return new Map(
345			listing.map((path) => [
346				relative(root, path),
347				createHash("sha256").update(readFileSync(path)).digest("hex"),
348			]),
349		);
350	}
351	
352	describe("the credential", () => {
353		it("is required, and its absence stops the run naming it", () => {
354			const root = temporaryRoot();
355			const { ELEVENLABS_API_KEY: _dropped, ...env } = process.env;
356			const result = spawnSync(
357				"python3",
358				[
359					join(SCRIPTS, "generate-lesson-deck.py"),
360					join(FIXTURES, "lesson-02.md"),
361					"--assets-root",
362					root,
363				],
364				{ encoding: "utf-8", env },
365			);
366			expect(result.status).not.toBe(0);
367			expect(result.stderr).toContain("ELEVENLABS_API_KEY");
368			// Not a partial run that reads as a success: nothing was written.
369			expect(existsSync(join(root, "lesson-02"))).toBe(false);
370		});
371	
372		it("never reaches a committed artifact, even when the vendor echoes it back", () => {
373			for (const path of ["deck.json", "manifest.json"]) {
374				expect(
375					keyShapedIn(readFileSync(join(FIXTURE_LESSON, path), "utf-8")),
376				).toEqual([]);
377			}
378	
379			const root = temporaryRoot();
380			const result = runScripted("vendor-echoes-key.json", root);
381			expect(result.status).not.toBe(0);
382			const manifest = readFileSync(
383				join(root, "lesson-02", "manifest.json"),
384				"utf-8",
385			);
386			for (const text of [manifest, result.stdout, result.stderr]) {
387				expect(text).not.toContain(FAKE_KEY);
388				expect(keyShapedIn(text)).toEqual([]);
389			}
390			// The diagnostic survives — echoing the vendor's body back is the whole
391			// value of the error — and the credential inside it does not.
392			expect(manifest).toContain("401 from the vendor");
393			expect(manifest).toContain("[redacted]");
394		});
395	});
396	
397	/**
398	 * Anything in a committed artifact that could be a credential: an `sk_`-
399	 * prefixed token, or a credential-named field holding something other than the
400	 * redaction marker. Content hashes are hex and much longer, so a blind
401	 * long-token scan would drown in them.
402	 */
403	function keyShapedIn(text: string): string[] {
404		const prefixed = text.match(/sk_[A-Za-z0-9]{16,}/g) ?? [];
405		const named = [
406			...text.matchAll(/(?:xi-)?api[-_]?key[^A-Za-z0-9[]{1,8}(\S{8,})/gi),
407		]
408			.map((match) => match[1])
409			.filter((value) => !value.startsWith("[redacted]"));
410		return [...prefixed, ...named];
411	}
412	
413	describe("transcribing a Thai clip back", () => {
414		it("retries a mismatched take and records the outcome that finally passed", () => {
415			const root = temporaryRoot();
416			const run = report(runScripted("retry-then-pass.json", root));
417			expect(run.deckWritten).toBe(true);
418			// One extra synthesis and one extra transcription over the clean run:
419			// the Thai line was voiced twice.
420			expect(run.transcribeCalls).toBe(2);
421	
422			const manifest = readJson(
423				join(root, "lesson-02", "manifest.json"),
424			) as typeof fixtureManifest;
425			const thai = manifest.assets.filter((asset) => asset.language === "th");
426			expect(thai.length).toBeGreaterThan(0);
427			for (const asset of thai) {
428				expect(asset.state).toBe("generated");
429				expect(asset.verification?.outcome).toBe("verified");
430				expect(asset.verification?.attempts).toBe(2);
431			}
432			// English lines are not transcribed back, and say so rather than
433			// claiming a verification they never took.
434			for (const asset of manifest.assets.filter((a) => a.language === "en")) {
435				expect(asset.verification?.outcome).toBe("not-required");
436			}
437		});
438	
439		it("ships no clip that never verified, and no deck either", () => {
440			const root = temporaryRoot();
441			const result = runScripted("never-verifies.json", root);
442			expect(result.status).not.toBe(0);
443			const run = JSON.parse(result.stdout) as RunReport;
444			expect(run.failed).toBe(1);
445			expect(run.deckWritten).toBe(false);
446			expect(existsSync(join(root, "lesson-02", "deck.json"))).toBe(false);
447	
448			const manifest = readJson(
449				join(root, "lesson-02", "manifest.json"),
450			) as typeof fixtureManifest;
451			const failed = manifest.assets.filter((asset) => asset.state === "failed");
452			expect(failed).toHaveLength(1);
453			expect(failed[0].language).toBe("th");
454			expect(failed[0].verification?.outcome).toBe("mismatch");
455			expect(failed[0].path).toBeNull();
456		});
457	});
458	
459	describe("the three segment states", () => {
460		it("are three distinct values, declared on the manifest itself", () => {
461			const states = fixtureManifest.schema.segmentStates;
462			expect(states).toEqual(["absent", "generated", "failed"]);
463			expect(new Set(states).size).toBe(3);
464		});
465	
466		it("record a failed segment as failed, never as one that is simply absent", () => {
467			const root = temporaryRoot();
468			runScripted("never-verifies.json", root);
469			const manifest = readJson(
470				join(root, "lesson-02", "manifest.json"),
471			) as typeof fixtureManifest;
472			expect(new Set(manifest.schema.segmentStates).size).toBe(3);
473	
474			// Every declared segment is present with a state; the failed one is
475			// neither omitted from the manifest nor recorded as never generated.
476			const states = new Map(
477				manifest.assets.map((asset) => [asset.key, asset.state]),
478			);
479			expect(states.size).toBe(fixtureManifest.assets.length);
480			expect(states.get("district-1")).toBe("failed");
481			expect([...states.values()]).not.toContain("absent");
482			for (const state of states.values()) {
483				expect(manifest.schema.segmentStates).toContain(state);
484			}
485			// The manifest declares two vocabularies; both are checked against the
486			// assets that use them, or the unchecked one drifts.
487			for (const asset of manifest.assets) {
488				if (!asset.verification) continue;
489				expect(manifest.schema.verificationOutcomes).toContain(
490					asset.verification.outcome,
491				);
492			}
493		});
494	});
